  values ('ME', 'short_answer', 'What is a transistor used for in electronic circuits? How does an operational amplifier (op-amp) work?', 'A transistor (BJT or FET) is a semiconductor device in which a small input (base current or gate voltage) controls a larger current between collector-emitter or drain-source. It is used as an amplifier (radios, audio, sensors) and as a fast electronic switch (digital logic, motor and LED drivers), and billions of transistors form integrated circuits and processors. An op-amp is an integrated differential amplifier with two inputs (inverting - and non-inverting +), very high open-loop gain (about 10⁵-10⁶), very high input impedance and low output impedance; its output is Vo = A(V+ - V-). Because the gain is so large, it is used with negative feedback resistors that set a precise gain: inverting amplifier gain = -Rf/Rin, non-inverting gain = 1 + Rf/Rin. It is also used as a comparator, summing amplifier, integrator, differentiator and active filter.', null, '[{"point": "Transistor: amplifier (small base/ gate signal controls larger current) and electronic switch (digital logic, drivers); BJT/ FET types; building block of ICs", "marks": 2.5}, {"point": "Op-amp: differential amplifier with very high open-loop gain, high input impedance, low output impedance; output = A(V+ - V-); used with negative feedback to set gain (inverting -Rf/Rin, non-inverting 1 + Rf/Rin), comparators, filters, integrators", "marks": 2.5}]'::jsonb, (select id from public.subjects where slug = 'subject-specialisation'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'subject-specialisation') and t.slug = 'electronics-and-communication-engineering'), (select id from public.exam_papers where code = 'me-technical-3'), 'standard', 5,
    540, 'historical_official', 'awaiting_review',
    null, null,
    '{"verdict": "pass", "issues": [], "checker_notes": "Model answer, marking guide and rubric written by Claude from the RCSC paper; facts were checked against what is widely published, but please read before publishing. Real past-paper questions keep RCSC wording.", "batch": "ME Paper III (Technical, Electronics and Communication Engineering): BCSE 2024, batch 1", "source": {"title": "BCSE 2024 Main Examination, Technical Paper III, Electronics and Communication Engineering", "year": 2024, "url": "https://rcsc.gov.bt/technical-paper-iii/"}}'::jsonb, null, null, null, null, (select id from public.specialisations where code = 'electronics-communication-engineering'), null)
